def cards(items, cls='cards-3'):
    out=''
    for it in items:
        title=it[0]; text=it[1]; ic=it[2] if len(it)>2 else 'check'
        out += f'<article class="info-card">{icon(ic)}<h3>{title}</h3><p>{text}</p></article>'
    return f'<div class="{cls}">{out}</div>'

